<?php $lines=cart_lines();if(!$lines){redirect(route('cart'));}$subtotal=cart_subtotal($lines);$shipping=config('shipping_millimes');$checkoutReady=$shipping!==null;foreach($lines as $l)$checkoutReady=$checkoutReady&&$l['price_millimes']!==null&&(int)$l['price_millimes']>0&&(int)$l['stock']>=$l['quantity']&&(int)$l['active']===1;$old=$_SESSION['checkout_old']??[];unset($_SESSION['checkout_old']);$_SESSION['checkout_key']??=bin2hex(random_bytes(24));?>
<main id="main" class="content-page"><div class="page-heading"><p class="eyebrow">LA DERNIÈRE ÉTAPE</p><h1>À votre adresse.</h1><p>Paiement à la livraison · Tunisie</p></div><div class="checkout-layout"><form class="checkout-form" method="post" action="<?=e(url('actions/order.php'))?>"><?=csrf_input()?><input type="hidden" name="checkout_key" value="<?=e($_SESSION['checkout_key'])?>"><h2>Vos coordonnées</h2><div class="form-grid"><label class="field">Nom complet<input name="name" autocomplete="name" maxlength="120" required value="<?=e($old['name']??user()['name']??'')?>"></label><label class="field">E-mail<input type="email" name="email" autocomplete="email" maxlength="190" required value="<?=e($old['email']??user()['email']??'')?>"></label><label class="field">Téléphone<input name="phone" type="tel" autocomplete="tel" pattern="(?:\+216|00216)?[0-9 ]{8,14}" placeholder="Téléphone tunisien" maxlength="20" required value="<?=e($old['phone']??'')?>"></label><label class="field">Gouvernorat<select name="governorate" required><option value="">Choisir</option><?php foreach(governorates() as $g):?><option <?=$g===($old['governorate']??'')?'selected':''?>><?=e($g)?></option><?php endforeach;?></select></label></div><label class="field">Adresse complète<textarea name="address" autocomplete="street-address" maxlength="500" rows="3" required><?=e($old['address']??'')?></textarea></label><label class="field">Code postal<input name="postal_code" autocomplete="postal-code" pattern="[0-9]{4}" maxlength="4" required value="<?=e($old['postal_code']??'')?>"></label><label class="field">Une précision pour la livraison ?<textarea name="notes" rows="2" maxlength="500"><?=e($old['notes']??'')?></textarea></label><label class="check-label"><input type="checkbox" name="terms" value="1" required> J’ai lu les <a href="<?=e(route('policy',['section'=>'terms']))?>">conditions de vente</a> et la <a href="<?=e(route('policy',['section'=>'privacy']))?>">politique de confidentialité</a>.</label><?php if(!$checkoutReady):?><p role="alert" class="flash">La disponibilité et les frais de livraison doivent être confirmés avant validation.</p><?php endif;?><button type="submit" class="button" <?=$checkoutReady?'':'disabled'?>>Confirmer ma commande</button><p class="form-note">Aucun paiement bancaire n’est demandé sur ce site.</p></form><aside class="cart-summary"><h2>Votre sélection</h2><?php foreach($lines as $l):?><div><span><?=e($l['name'])?> ×<?=$l['quantity']?><small><?=e($l['color_name'].' / '.$l['size_label'])?></small></span><strong><?=e(money((int)$l['price_millimes']*$l['quantity']))?></strong></div><?php endforeach;?><div><span>Sous-total</span><strong><?=e(money($subtotal))?></strong></div><div><span>Livraison</span><strong><?=$shipping===null?'À confirmer':e(money($shipping))?></strong></div><div class="total"><span>Total</span><strong><?=$shipping===null?'À confirmer':e(money($subtotal+$shipping))?></strong></div></aside></div></main>